verifier.cmd:
d=$(mktemp -d) && cp -R . "$d/r" && cd "$d/r" && printf '
export function zzTestOnly() { return 1; }
' >> src/engine/util.mjs && printf "import { zzTestOnly } from '../src/engine/util.mjs';
void zzTestOnly;
" > test/zz-probe.test.mjs && printf '
export function zzDispatched() { return 1; }
' >> src/cli/upgrade.mjs && printf 'export function zzStringPath() { return 1; }
' > src/engine/zz-probe.mjs && printf "
const zzPath = '../engine/zz-probe.mjs'; void zzPath;
" >> src/cli/doctor.mjs || exit 1; out=$(node --test test/dead-code.test.mjs 2>&1); rc=$?; cd / && rm -rf "$d"; [ $rc -ne 0 ] || exit 1; for n in zzTestOnly zzDispatched zzStringPath; do printf '%s
' "$out" | grep -q "$n" || exit 1; done

d=$(mktemp -d) && cp -R . "$d/r" && cd "$d/r" && printf '
export const zzArrow = () => 1;
export function* zzGen() { yield 1; }
function zzListed() { return 1; }
export { zzListed };
export class ZzClass {}
' >> src/engine/util.mjs || exit 1; out=$(node --test test/dead-code.test.mjs 2>&1); rc=$?; cd / && rm -rf "$d"; [ $rc -ne 0 ] || exit 1; for n in zzArrow zzGen zzListed ZzClass; do printf '%s
' "$out" | grep -q "$n" || exit 1; done
